.ocrw-summary-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-top:14px;}
.ocrw-summary-card{padding:16px;border-radius:20px;border:1px solid var(--line);background:var(--soft);}
.ocrw-summary-card span{display:block;color:var(--muted);font-size:12px;margin-bottom:8px;}
.ocrw-summary-card strong{font-size:28px;line-height:1.05;}
.ocrw-report-table-wrap{margin-top:14px;border:1px solid var(--line);border-radius:20px;overflow:auto;background:var(--card);}
.ocrw-report-table{width:100%;border-collapse:collapse;min-width:560px;}
.ocrw-report-table th,.ocrw-report-table td{padding:12px 14px;border-bottom:1px solid var(--line);text-align:left;font-size:14px;}
.ocrw-report-table th{position:sticky;top:0;background:var(--card-2);z-index:1;}
.ocrw-modal-backdrop{position:fixed;inset:0;background:rgba(15,23,42,.55);backdrop-filter:blur(10px);display:none;align-items:center;justify-content:center;padding:18px;z-index:1400;}
.ocrw-modal-backdrop.is-open{display:flex;}
.ocrw-modal-card{width:min(440px,100%);padding:18px;border-radius:24px;border:1px solid var(--line);background:linear-gradient(180deg,var(--card),var(--card-2));box-shadow:0 24px 70px rgba(0,0,0,.25);}
.ocrw-modal-card h3{margin:0;font-size:22px;}
.ocrw-modal-card p{margin:8px 0 0;color:var(--muted);line-height:1.45;}
.ocrw-note{color:var(--muted);font-size:13px;line-height:1.45;}
.ocrw-hidden{display:none!important;}
.ocrw-root .cropper-view-box{outline:3px solid rgba(var(--primary-rgb),.95)!important;box-shadow:0 0 0 1px rgba(255,255,255,.75)!important;}
.ocrw-root .cropper-face{background:rgba(var(--primary-rgb),.08)!important;}
.ocrw-root .cropper-line{background:rgba(var(--primary-rgb),.8)!important;}
.ocrw-root .cropper-point{width:30px!important;height:30px!important;opacity:1!important;background:#fff!important;border:3px solid var(--primary)!important;border-radius:999px!important;box-shadow:0 8px 22px rgba(0,0,0,.28)!important;}
.ocrw-root .cropper-point.point-e,.ocrw-root .cropper-point.point-w{top:50%!important;margin-top:-15px!important;}
.ocrw-root .cropper-point.point-n,.ocrw-root .cropper-point.point-s{left:50%!important;margin-left:-15px!important;}
.ocrw-root .cropper-point.point-nw{left:-15px!important;top:-15px!important;}
.ocrw-root .cropper-point.point-ne{right:-15px!important;top:-15px!important;}
.ocrw-root .cropper-point.point-sw{left:-15px!important;bottom:-15px!important;}
.ocrw-root .cropper-point.point-se{right:-15px!important;bottom:-15px!important;}
.ocrw-root .cropper-point.point-w{left:-15px!important;}
.ocrw-root .cropper-point.point-e{right:-15px!important;}
.ocrw-root .cropper-point.point-n{top:-15px!important;}
.ocrw-root .cropper-point.point-s{bottom:-15px!important;}
@media (max-width:900px){.ocrw-shell{padding:12px;}.ocrw-hero{padding:18px;flex-direction:column;align-items:stretch;}.ocrw-stepper{display:grid;overflow:visible;padding-bottom:2px;}.ocrw-step{min-width:0;}.ocrw-crop-layout,.ocrw-resolve-row{grid-template-columns:1fr;}.ocrw-crop-frame{height:min(54vh,calc(100dvh - 360px));}.ocrw-thumb-list{max-height:220px;}.ocrw-stat-grid,.ocrw-summary-grid{grid-template-columns:repeat(2,minmax(0,1fr));}}
@media (max-width:640px){.ocrw-shell{padding:8px;}.ocrw-card{border-radius:20px;}.ocrw-hero h1{font-size:24px;}.ocrw-panel{padding:14px;}.ocrw-panel-head{flex-direction:column;}.ocrw-dropzone{padding:20px;min-height:180px;border-radius:18px;}.ocrw-dropzone h3{font-size:20px;}.ocrw-preview-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;}.ocrw-crop-frame{height:min(46vh,calc(100dvh - 390px));min-height:220px;}.ocrw-thumb{grid-template-columns:62px minmax(0,1fr);}.ocrw-thumb img{width:62px;height:62px;}.ocrw-thumb-list{max-height:180px;}.ocrw-stat-grid,.ocrw-summary-grid{grid-template-columns:1fr;}.ocrw-resolve-actions{grid-template-columns:1fr;}.ocrw-btn-row{flex-direction:column;}.ocrw-btn{width:100%;}.ocrw-report-table{min-width:0;}.ocrw-report-table th,.ocrw-report-table td{padding:10px 12px;font-size:13px;}.ocrw-hero-badge,.ocrw-badge{width:100%;justify-content:center;}.ocrw-root .cropper-point{width:34px!important;height:34px!important;}.ocrw-root .cropper-point.point-e,.ocrw-root .cropper-point.point-w{margin-top:-17px!important;}.ocrw-root .cropper-point.point-n,.ocrw-root .cropper-point.point-s{margin-left:-17px!important;}.ocrw-root .cropper-point.point-nw{left:-17px!important;top:-17px!important;}.ocrw-root .cropper-point.point-ne{right:-17px!important;top:-17px!important;}.ocrw-root .cropper-point.point-sw{left:-17px!important;bottom:-17px!important;}.ocrw-root .cropper-point.point-se{right:-17px!important;bottom:-17px!important;}.ocrw-root .cropper-point.point-w{left:-17px!important;}.ocrw-root .cropper-point.point-e{right:-17px!important;}.ocrw-root .cropper-point.point-n{top:-17px!important;}.ocrw-root .cropper-point.point-s{bottom:-17px!important;}}
</style>
