<script>
(()=>{const root=document.getElementById(<?= json_encode($ocrRootId) ?>);if(!root||root.dataset.booted==='1')return;root.dataset.booted='1';const OCR_API_BASE=<?= json_encode($ocrApiBase) ?>;const tr=<?= json_encode($ocrT,JSON_UNESCAPED_UNICODE) ?>;const q=role=>root.querySelector(`[data-ocr-role="${role}"]`);const qa=selector=>Array.from(root.querySelectorAll(selector));const state={step:1,items:[],cropper:null,cropIndex:0,jobId:'',pollTimer:null,report:null,stores:[],selection:{},createRaw:'',finalizing:false};const photosInput=q('photos-input');const dropzone=q('dropzone');const uploadPreviews=q('upload-previews');const uploadContinue=q('upload-continue');const cropEmpty=q('crop-empty');const cropLayout=q('crop-layout');const cropImage=q('crop-image');const cropThumbs=q('crop-thumbs');const resolveList=q('resolve-list');const resolveEmpty=q('resolve-empty');const scanWarningsWrap=q('scan-warnings-wrap');const scanWarnings=q('scan-warnings');const createStoreModal=q('create-store-modal');const createStoreInput=q('create-store-input');function tp(s,m){if(!s)return'';let out=s;Object.keys(m||{}).forEach(k=>{out=out.split('{'+k+'}').join(String(m[k]??''));});return out;}function escHtml(s){return String(s??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}function apiUrl(query=''){return `${OCR_API_BASE}${query}`;}function emitProgress(lines){if(typeof window.handleEmbeddedOCRProgress==='function')window.handleEmbeddedOCRProgress(lines);if(window.parent&&window.parent!==window)window.parent.postMessage({type:'ocr_progress',lines},'*');}function emitFinished(message){if(typeof window.handleEmbeddedOCRFinished==='function')window.handleEmbeddedOCRFinished(message,state.report||null);if(window.parent&&window.parent!==window)window.parent.postMessage({type:'ocr_finished',message},'*');}function heroTextByStep(step){const map={1:tr.hero_idle,2:tr.hero_crop,3:tr.hero_scan,4:tr.hero_resolve,5:tr.hero_report};return map[step]||tr.hero_idle;}function setHeroStatus(text){q('hero-status').textContent=text;}function pulseHeroStatus(text){setHeroStatus(text);window.clearTimeout(pulseHeroStatus.timer);pulseHeroStatus.timer=window.setTimeout(()=>setHeroStatus(heroTextByStep(state.step)),1800);}function formatWarn(w){if(typeof w==='string')return w;if(!w||!w.code)return JSON.stringify(w);if(w.code==='no_rates')return tr.warn_no_rates||'';if(w.code==='skip_no_rate')return tp(tr.warn_skip_no_rate||'',{merchant:w.merchant||'',currency:w.currency||'',amount:w.amount||''});if(w.code==='no_amount_in_file')return tp(tr.warn_no_amount_in_file||'',{file:w.file||''});if(w.code==='file_error')return tp(tr.warn_file_error||'',{file:w.file||'',message:w.message||''});if(w.code==='already_imported')return tp(tr.warn_already_imported||'',{date:w.date||'',store:w.store||'',amount:w.amount||''});return JSON.stringify(w);}function setStep(step){state.step=step;qa('.ocrw-panel').forEach(panel=>panel.classList.toggle('is-active',Number(panel.dataset.ocrPanel)===step));qa('.ocrw-step').forEach(node=>{const value=Number(node.dataset.ocrStep);node.classList.toggle('is-active',value===step);node.classList.toggle('is-done',value<step);});setHeroStatus(heroTextByStep(step));}function revokeStateUrls(){state.items.forEach(item=>{if(item.url)URL.revokeObjectURL(item.url);if(item.croppedUrl)URL.revokeObjectURL(item.croppedUrl);});}function ensureItems(list){revokeStateUrls();state.items=[...list].filter(file=>String(file.type||'').startsWith('image/')).map((file,index)=>({id:`item-${index}-${Date.now()}`,file,name:file.name||`${tr.photo} ${index+1}`,url:URL.createObjectURL(file),croppedBlob:null,croppedUrl:'',isCropped:false}));state.cropIndex=0;renderUploadStep();renderCropStep();}function previewUrl(item){return item.croppedUrl||item.url;}function renderUploadStep(){q('upload-count-badge').textContent=String(state.items.length);uploadContinue.disabled=!state.items.length;uploadPreviews.innerHTML=state.items.length?state.items.map((item,index)=>`<div class="ocrw-preview-card"><span class="ocrw-preview-tag">${escHtml(item.isCropped?tr.step_crop:tr.photo+' '+(index+1))}</span><img src="${escHtml(previewUrl(item))}" alt="${escHtml(item.name)}"><div class="ocrw-preview-meta"><span>${escHtml(item.name)}</span><span>${index+1}</span></div></div>`).join(''):`<div class="ocrw-empty" style="grid-column:1/-1;">${escHtml(tr.no_files)}</div>`;}function destroyCropper(){if(state.cropper){state.cropper.destroy();state.cropper=null;}}function updateCropBadge(){q('crop-progress-badge').textContent=`${state.items.length?state.cropIndex+1:0}/${state.items.length}`;}function selectCropIndex(index){if(!state.items.length)return;state.cropIndex=Math.max(0,Math.min(index,state.items.length-1));updateCropBadge();q('crop-current-name').textContent=state.items[state.cropIndex].name;q('crop-current-note').textContent=state.items[state.cropIndex].isCropped?tr.apply_crop:tr.crop_hint;qa('.ocrw-thumb').forEach((node,i)=>node.classList.toggle('is-active',i===state.cropIndex));destroyCropper();cropImage.onload=()=>{if(typeof Cropper!=='undefined'){state.cropper=new Cropper(cropImage,{viewMode:1,autoCropArea:1,background:false,responsive:true,checkOrientation:false,minContainerWidth:300,minContainerHeight:300});}};cropImage.src=previewUrl(state.items[state.cropIndex]);}function renderCropStep(){if(!state.items.length){cropEmpty.classList.remove('ocrw-hidden');cropLayout.classList.add('ocrw-hidden');updateCropBadge();return;}cropEmpty.classList.add('ocrw-hidden');cropLayout.classList.remove('ocrw-hidden');cropThumbs.innerHTML=state.items.map((item,index)=>`<button type="button" class="ocrw-thumb${index===state.cropIndex?' is-active':''}" data-index="${index}"><img src="${escHtml(previewUrl(item))}" alt="${escHtml(item.name)}"><div><div class="ocrw-thumb-name">${escHtml(item.name)}</div><div class="ocrw-thumb-note">${escHtml(item.isCropped?tr.apply_crop:tr.photo+' '+(index+1))}</div></div></button>`).join('');qa('.ocrw-thumb').forEach(node=>node.onclick=()=>selectCropIndex(Number(node.dataset.index)));selectCropIndex(Math.min(state.cropIndex,state.items.length-1));}function blobFromCanvas(canvas){return new Promise(resolve=>canvas.toBlob(blob=>resolve(blob),'image/jpeg',0.92));}async function applyCrop(){if(!state.items.length||!state.cropper)return;const canvas=state.cropper.getCroppedCanvas({maxWidth:2200,maxHeight:2200,imageSmoothingEnabled:true,imageSmoothingQuality:'high'});if(!canvas)return;const blob=await blobFromCanvas(canvas);if(!blob)return;const item=state.items[state.cropIndex];if(item.croppedUrl)URL.revokeObjectURL(item.croppedUrl);item.croppedBlob=new File([blob],item.file.name||`crop-${state.cropIndex+1}.jpg`,{type:'image/jpeg'});item.croppedUrl=URL.createObjectURL(item.croppedBlob);item.isCropped=true;renderUploadStep();renderCropStep();}function resetCrop(){if(!state.items.length)return;const item=state.items[state.cropIndex];if(item.croppedUrl)URL.revokeObjectURL(item.croppedUrl);item.croppedBlob=null;item.croppedUrl='';item.isCropped=false;renderUploadStep();renderCropStep();}async function api(query,options={}){const response=await fetch(apiUrl(query),options);const text=await response.text();if(!text){throw new Error(tr.error||'Empty response');}try{return JSON.parse(text);}catch(e){throw new Error(text.slice(0,200)||tr.error);}}async function loadStores(){const data=await api('?api=stores');state.stores=Array.isArray(data.stores)?data.stores:[];}function renderWarningList(target,list){target.innerHTML=(list||[]).length?(list||[]).map(item=>`<div class="ocrw-warn-item">${escHtml(formatWarn(item))}</div>`).join(''):`<div class="ocrw-empty">${escHtml(tr.empty_warnings)}</div>`;}function setRecognitionStats(job){const progress=job.progress||{total:0,processed:0,percent:0};const rows=job.records||[];const recognized=job.recognized||rows;q('scan-total').textContent=String(progress.total||0);q('scan-processed').textContent=String(progress.processed||0);q('scan-records').textContent=String(rows.length||recognized.length);q('scan-unresolved').textContent=String((job.unresolved||[]).length);q('scan-currency').textContent=`${tr.currency}: ${job.base_currency||'—'}`;q('progress-fill').style.width=`${progress.percent||0}%`;q('progress-percent').textContent=`${Math.round(progress.percent||0)}%`;q('progress-text').textContent=tp(tr.progress_line,{cur:progress.processed||0,total:progress.total||0,pct:progress.percent||0});scanWarningsWrap.classList.toggle('ocrw-hidden',!(job.warnings||[]).length);renderWarningList(scanWarnings,job.warnings||[]);}function unresolvedSummaryRows(rows){const map=new Map();(rows||[]).forEach(item=>{const raw=String(item&&item.merchant_raw||'').trim();if(!raw)return;if(!map.has(raw)){map.set(raw,{raw,count:0,suggested:item.suggested_store||'',confidence:item.confidence||0});}const row=map.get(raw);row.count+=1;if(!row.suggested&&item.suggested_store)row.suggested=item.suggested_store;row.confidence=Math.max(Number(row.confidence||0),Number(item.confidence||0));});return [...map.values()];}function renderResolveStep(){const rows=unresolvedSummaryRows(state.report&&state.report.unresolved||[]);q('resolve-count-badge').textContent=String(rows.length);resolveList.innerHTML='';resolveEmpty.classList.toggle('ocrw-hidden',rows.length>0);if(!rows.length)return;resolveList.innerHTML=rows.map(row=>{const selected=state.selection[row.raw]||'';return `<div class="ocrw-resolve-row"><div class="ocrw-resolve-main"><div class="ocrw-resolve-raw">${escHtml(row.raw)}</div><div class="ocrw-resolve-sub"><span>${escHtml(tr.occurrences)}: ${row.count}</span>${row.suggested?`<span>${escHtml(tr.suggested)}: ${escHtml(row.suggested)}</span>`:''}${row.confidence?`<span>${Math.round(row.confidence*100)}%</span>`:''}</div></div><div class="ocrw-resolve-actions"><select class="ocrw-select" data-raw="${escHtml(row.raw)}"><option value="">${escHtml(tr.choose_store)}</option>${state.stores.map(store=>`<option value="${escHtml(store)}"${store===selected?' selected':''}>${escHtml(store)}</option>`).join('')}</select><button type="button" class="ocrw-btn ocrw-btn-secondary" data-create-raw="${escHtml(row.raw)}" data-create-name="${escHtml(row.suggested||row.raw)}">${escHtml(tr.create_store)}</button></div></div>`;}).join('');qa('.ocrw-select[data-raw]').forEach(select=>select.onchange=()=>{state.selection[select.dataset.raw]=select.value;});qa('[data-create-raw]').forEach(button=>button.onclick=()=>openCreateStore(button.dataset.createRaw,button.dataset.createName||button.dataset.createRaw));}function renderReport(){const job=state.report||{};const records=job.records||[];const warnings=job.warnings||[];const manualAdded=Number(job.manual_added||0);const unresolved=Number((job.unresolved||[]).length);const addedCount=Number(job.added_count||records.filter(row=>row.status==='added').length);q('report-currency').textContent=`${tr.currency}: ${job.base_currency||'—'}`;q('report-auto').textContent=String(addedCount);q('report-manual').textContent=String(manualAdded);q('report-remaining').textContent=String(unresolved);renderWarningList(q('report-warnings'),warnings);const hasRows=records.length>0;q('report-empty').classList.toggle('ocrw-hidden',hasRows);q('report-table-wrap').classList.toggle('ocrw-hidden',!hasRows);q('report-tbody').innerHTML=records.map(row=>{const badge=row.status==='duplicate'?` <span class="ocrw-note">${escHtml(tr.report_duplicate||'already imported')}</span>`:'';return `<tr><td>${escHtml(row.date||'')}</td><td>${escHtml(row.store||'')}${badge}</td><td>${escHtml(Number(row.amount||0).toFixed(2))} ${escHtml(job.base_currency||'')}</td></tr>`;}).join('');}async function startRecognition(){if(!state.items.length){setStep(1);return;}setStep(3);const fd=new FormData();state.items.forEach((item,index)=>fd.append('photos[]',item.croppedBlob||item.file,item.file.name||`photo-${index+1}.jpg`));q('progress-fill').style.width='0%';q('progress-percent').textContent='0%';q('progress-text').textContent=tr.loading;scanWarningsWrap.classList.add('ocrw-hidden');scanWarnings.innerHTML='';try{const data=await api('?api=start',{method:'POST',body:fd});if(data.status!=='ok'){q('progress-text').textContent=tp(tr.err_start,{message:data.message||tr.error});emitProgress([tp(tr.err_start,{message:data.message||tr.error})]);return;}state.jobId=data.job_id||'';q('scan-currency').textContent=`${tr.currency}: ${data.base_currency||'—'}`;emitProgress([tr.processing_title,`${tr.currency}: ${data.base_currency||'—'}`]);pollJob(state.jobId);}catch(error){q('progress-text').textContent=tp(tr.err_start,{message:error.message||tr.error});}}function stopPolling(){if(state.pollTimer){clearInterval(state.pollTimer);state.pollTimer=null;}}function finishRecognition(job){state.report=job;stopPolling();if((job.unresolved||[]).length){renderResolveStep();setStep(4);return;}renderReport();setStep(5);}async function pollJob(jobId){stopPolling();const tick=async()=>{try{const data=await api(`?api=status&job_id=${encodeURIComponent(jobId)}`);if(data.status!=='ok'){q('progress-text').textContent=tr.status_error;return;}const job=data.job||{};state.report=job;setRecognitionStats(job);emitProgress([q('progress-text').textContent,...(job.warnings||[]).map(formatWarn)]);if(job.state==='done'){finishRecognition(job);}if(job.state==='error'){stopPolling();q('progress-text').textContent=tp(tr.err_worker,{message:job.message||tr.error});emitProgress([tp(tr.err_worker,{message:job.message||tr.error})]);}}catch(error){q('progress-text').textContent=tp(tr.err_worker,{message:error.message||tr.error});}};await tick();state.pollTimer=setInterval(tick,1200);}function openCreateStore(raw,name){state.createRaw=raw;createStoreInput.value=name||raw||'';createStoreModal.classList.add('is-open');setTimeout(()=>{createStoreInput.focus();createStoreInput.select();},0);}function closeCreateStore(){state.createRaw='';createStoreModal.classList.remove('is-open');}async function saveCreatedStore(){const name=createStoreInput.value.trim();if(!name){createStoreInput.focus();return;}const data=await api('?api=create_store',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name})});if(data.status!=='ok')return;state.stores=Array.isArray(data.stores)?data.stores:state.stores;state.selection[state.createRaw]=name;closeCreateStore();renderResolveStep();pulseHeroStatus(tr.saved_store);}async function applyMappings(){const map={};Object.keys(state.selection).forEach(raw=>{if(state.selection[raw])map[raw]=state.selection[raw];});try{const data=await api('?api=resolve',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({job_id:state.jobId,map})});if(data.status!=='ok'){pulseHeroStatus(tp(tr.err_start,{message:data.message||tr.error}));return;}const status=await api(`?api=status&job_id=${encodeURIComponent(state.jobId)}`);if(status.status==='ok')state.report=status.job||state.report;renderResolveStep();pulseHeroStatus(tp(tr.mapping_saved,{count:data.added||0}));if((state.report&&state.report.unresolved||[]).length){emitProgress([tp(tr.mapping_saved,{count:data.added||0})]);return;}renderReport();setStep(5);}catch(error){pulseHeroStatus(tp(tr.err_start,{message:error.message||tr.error}));emitProgress([tp(tr.err_start,{message:error.message||tr.error})]);}}async function finalizeFlow(){if(state.finalizing)return;if(!state.jobId){emitFinished(tr.finish_done);return;}state.finalizing=true;const button=q('finish-btn');button.textContent=tr.finish_busy;button.disabled=true;try{const data=await api('?api=finalize',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({job_id:state.jobId})});if(data.status==='ok'){pulseHeroStatus(tr.cleanup_ok);emitFinished(tr.cleanup_ok);button.textContent=tr.finish_done;return;}button.textContent=tr.finish;button.disabled=false;state.finalizing=false;}catch(error){button.textContent=tr.finish;button.disabled=false;state.finalizing=false;}}async function restoreActiveJob(){await loadStores();try{const active=await api('?api=active_job');const jobId=active.job_id||'';if(!jobId)return;state.jobId=jobId;const status=await api(`?api=status&job_id=${encodeURIComponent(jobId)}`);if(status.status!=='ok')return;state.report=status.job||{};if(state.report.state==='queued'||state.report.state==='processing'){setStep(3);setRecognitionStats(state.report);pollJob(jobId);return;}if(state.report.state==='done'){if((state.report.unresolved||[]).length){renderResolveStep();setStep(4);return;}renderReport();setStep(5);return;}if(state.report.state==='error'){setStep(3);q('progress-text').textContent=tp(tr.err_worker,{message:state.report.message||tr.error});}}catch(error){}}photosInput.addEventListener('change',event=>ensureItems(event.target.files||[]));dropzone.addEventListener('dragover',event=>{event.preventDefault();dropzone.classList.add('is-drag');});dropzone.addEventListener('dragleave',()=>dropzone.classList.remove('is-drag'));dropzone.addEventListener('drop',event=>{event.preventDefault();dropzone.classList.remove('is-drag');ensureItems(event.dataTransfer.files||[]);});uploadContinue.onclick=()=>{if(!state.items.length)return;setStep(2);renderCropStep();};q('crop-apply').onclick=applyCrop;q('crop-reset').onclick=resetCrop;q('crop-skip').onclick=startRecognition;q('crop-continue').onclick=startRecognition;q('resolve-apply').onclick=applyMappings;q('resolve-skip').onclick=()=>{renderReport();setStep(5);};q('finish-btn').onclick=finalizeFlow;q('create-store-save').onclick=saveCreatedStore;q('create-store-cancel').onclick=closeCreateStore;createStoreModal.addEventListener('click',event=>{if(event.target===createStoreModal)closeCreateStore();});window.addEventListener('beforeunload',()=>{stopPolling();destroyCropper();});setStep(1);renderUploadStep();renderCropStep();restoreActiveJob();window.embeddedOcrWizard={restore:restoreActiveJob};})();
</script>
